INSERT INTO ANALYTICS_DDL2  VALUES  ((SELECT MAX(MODELCOD)+1 FROM ANALYTICS_DDL2),'Douglas','DC-10','3');
INSERT INTO ANALYTICS_DDL2  VALUES  ((SELECT MAX(MODELCOD)+1 FROM ANALYTICS_DDL2),'Boeing','737','2');
